function validate([edges, coins, k]) {
  const n = Array.isArray(coins) ? coins.length : 0;
  if (n < 2 || n > 100000) return 'coins needs 2 to 10^5 values.';
  if (coins.some(c => !Number.isInteger(c) || c < 0 || c > 10000)) return 'Each coins[i] is an integer from 0 to 10^4.';
  if (!Number.isInteger(k) || k < 0 || k > 10000) return 'k is an integer from 0 to 10^4.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must have exactly n - 1 edges.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 || edge.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each edge is a pair of node labels from 0 to n - 1.';
    const a = find(edge[0]), b = find(edge[1]);
    if (a === b) return 'The edges must form a tree (no cycles).';
    root[a] = b;
  }
  return null;
}

