function maximumPoints(edges, coins, k) {
  const n = coins.length;
  const LIMIT = 14;
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let head = 0; head < order.length; head++) {
    const node = order[head];
    for (const next of graph[node]) {
      if (next === parent[node]) continue;
      parent[next] = node;
      order.push(next);
    }
  }

  const dp = Array.from({ length: n }, () => new Array(LIMIT + 1).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    const node = order[i];
    for (let t = 0; t < LIMIT; t++) {
      let keep = (coins[node] >> t) - k;
      let halve = coins[node] >> (t + 1);
      for (const child of graph[node]) {
        if (child === parent[node]) continue;
        keep += dp[child][t];
        halve += dp[child][t + 1];
      }
      dp[node][t] = Math.max(keep, halve);
    }
  }
  return dp[0][0];
}

