function maximumPoints(edges, coins, k) {
  // Try every assignment of a way to every node and score it directly.
  const n = coins.length;
  const adjacent = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adjacent[a].push(b); adjacent[b].push(a); }
  const up = new Array(n).fill(-1);
  const seen = new Array(n).fill(false);
  const stack = [0];
  seen[0] = true;
  while (stack.length) {
    const x = stack.pop();
    for (const y of adjacent[x]) if (!seen[y]) { seen[y] = true; up[y] = x; stack.push(y); }
  }
  let best = -Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    let total = 0;
    for (let v = 0; v < n; v++) {
      let c = coins[v];
      for (let a = up[v]; a !== -1; a = up[a]) if (mask & (1 << a)) c = Math.floor(c / 2);
      total += (mask & (1 << v)) ? Math.floor(c / 2) : c - k;
    }
    best = Math.max(best, total);
  }
  return best;
}

