function generate(rand, size) {
  const pick = (m) => Math.floor(rand() * m);
  const n = size === 'large' ? 2000 - pick(3) : 2 + pick(8);
  const shape = rand();
  const top = [10, 100, 1000, 10000][pick(4)];
  const coins = Array.from({ length: n }, () => (rand() < 0.1 ? 0 : pick(top + 1)));
  const k = rand() < 0.1 ? 0 : pick(top + 1);
  // Build the tree on positions 0..n-1, each joining an earlier one, then relabel all but the root at random.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 1; i--) { const j = 1 + pick(i); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) {
    const parent = shape < 0.3 ? i - 1 : shape < 0.45 ? 0 : shape < 0.7 ? Math.max(0, i - 1 - pick(3)) : pick(i);
    const edge = [label[parent], label[i]];
    if (rand() < 0.5) edge.reverse();
    edges.push(edge);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [edges, coins, k];
}
